-- DINO REALMS Cloudflare D1 schema
CREATE TABLE IF NOT EXISTS players (player_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, age INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_seen TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scores (id INTEGER PRIMARY KEY AUTOINCREMENT, player_id TEXT NOT NULL, player_name TEXT NOT NULL, distance INTEGER NOT NULL DEFAULT 0, dino TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_scores_distance ON scores(distance DESC);
CREATE TABLE IF NOT EXISTS visits (id INTEGER PRIMARY KEY AUTOINCREMENT, player_id TEXT, visited_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS player_saves (player_id TEXT PRIMARY KEY, save_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS owner_accounts (player_id TEXT PRIMARY KEY, granted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
